SELECT (bd:year(?port_date) AS ?year) WHERE {
  ?event wdt:P31 wd:Q273692;
         wdt:P1545 wd:Q50565992;
         wdt:P585 ?event_date;
         wdt:P925 ?prize;
         wdt:P276 ?city.
  ?city wdt:P1348 ?port_date.
  ?prize ps:P925 ?prizeValue.
  FILTER (?event_date >= "2018-01-01T00:00:00Z"^^xsd:dateTime && ?event_date <= "2018-12-31T23:59:59Z"^^xsd:dateTime)
  FILTER (isNumeric(?prizeValue))
} ORDER BY DESC(?prizeValue) LIMIT 1

